using System;using System.Collections.Generic;
public static class CombatV01FormulaChecks {
 public static string Run(){int count=0;var failures=new List<string>();Action<bool,string> check=(ok,label)=>{count++;if(!ok)failures.Add(label);};Action<double,double,string> near=(a,b,label)=>check(Math.Abs(a-b)<1e-7,label+" actual="+a);double[] attacks={260,360,460};double[][] levels={new[]{130d,180,230},new[]{86.66666666666667,120,153.33333333333333},new[]{65d,90,115}};int[][] stops={new[]{7,9,12},new[]{5,6,8},new[]{4,5,6}};
 for(int scenario=0;scenario<3;scenario++)for(int i=0;i<3;i++){var r=CombatV01Formula.Resolve(attacks[i],100,0,scenario*100,false,false,0);near(r.H,levels[scenario][i],"TG level "+scenario+" "+i);check(r.hitstopFrames==stops[scenario][i],"ratio stop "+scenario+" "+i);check(r.outcome==(r.H<=100?CombatV01Outcome.Block:CombatV01Outcome.Hit),"unrounded classification");}
 for(int i=0;i<3;i++){var r=CombatV01Formula.Resolve(attacks[i],100,100,0,false,false,0);near(r.H,new[]{195d,270,345}[i],"attack100 H");check(r.stunFrames==new[]{20,27,35}[i]&&r.hitstopFrames==new[]{10,14,18}[i],"attack100 durations");near(CombatV01Formula.Resolve(attacks[i],100,100,100,false,false,0).H,levels[0][i],"equal100 ratio");}
 near(CombatV01Formula.HitLevel(460,180,0,0),164.28571428571428,"D180 holds strong");near(CombatV01Formula.HitLevel(360,180,200,80),183.6734693877551,"D180 interrupted by TG ratio");check(CombatV01Formula.Resolve(200,100,0,0,false,false,0).outcome==CombatV01Outcome.Block,"H equals B Block");check(CombatV01Formula.Resolve(200.1,100,0,0,false,false,0).outcome==CombatV01Outcome.Hit,"unrounded >B hit");check(CombatV01Formula.Resolve(200.1,100,0,0,true,false,10).stunFrames==1,"positive .005F ceil once");var negative=CombatV01Formula.Resolve(180,100,0,0,true,false,10);check(negative.stunFrames==0,"negative guard zero");near(negative.surplus,1,"negative surplus only");check(CombatV01Formula.Resolve(200,100,0,0,true,false,10).stunFrames==0,"exact zero remains zero");
 for(int age=-1;age<=31;age++){check(CombatV01Formula.JGReduction(age,false)==(age<0||age>29?0:10-age/3),"normal age "+age);check(CombatV01Formula.JGReduction(age,true)==(age<0||age>19?0:10-age/2),"continuous age "+age);}
 foreach(double a in new[]{260d,460})foreach(int jg in new[]{0,10}){double k=a/2*.001;var normal=CombatV01Formula.Resolve(a,100,0,0,true,false,jg);near(normal.selfPush,k*(jg==0?1:.6),"normal self push");var fd=CombatV01Formula.Resolve(a,100,0,0,true,true,jg);near(fd.selfPush,k,"FD self not JG reduced");near(fd.attackerPush,k*(jg==0?.2:.5),"FD attacker push");near(fd.damage,0,"FD chip immune");}
 foreach(double chip in new[]{.1,.2,.6}){near(CombatV01Formula.Resolve(260,100,0,0,true,false,0,1,chip).damage,130*chip,"fractional chip");near(CombatV01Formula.Resolve(260,100,0,0,false,false,0,.333,chip).damage,43.29,"fractional hit damage");}
 double sum=0,last=double.MaxValue;for(int f=0;f<10;f++){double step=CombatV01Formula.PushStep(.23,f);check(step>0&&step<last,"smooth decreasing push "+f);last=step;sum+=step;}near(sum,.23,"push integrates exact distance");check(CombatV01Formula.PushStep(.23,10)==0,"push ends at10");check(CombatV01Formula.TGMultiplier(-100)==.5,"confirmed negative TG multiplier");bool rejected=false;try{CombatV01Formula.Resolve(double.NaN,0,0,0,false,false,0);}catch(ArgumentOutOfRangeException){rejected=true;}check(rejected,"nonfinite rejected");if(failures.Count>0)throw new Exception(string.Join("\n",failures));return count+" PASS, 0 FAIL";}
}
